import { useEffect, useState } from "react";
import feather from "feather-icons";
import axios from "axios";

export default function Internship() {
  const [formData, setFormData] = useState({
    internship_offers: "",
    first_name: "",
    last_name: "",
    email: "",
    phone_number: "",
    education: "",
    resume: null,
    reason: "", // optional
  });

  useEffect(() => {
    feather.replace();
  }, []);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleFileChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      resume: e.target.files[0],
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    data.append("internship_offers", formData.internship_offers); // FK ID
    data.append("first_name", formData.first_name);
    data.append("last_name", formData.last_name);
    data.append("email", formData.email);
    data.append("phone_number", formData.phone_number);
    data.append("education", formData.education);
    data.append("resume", formData.resume);

    if (formData.reason.trim() !== "") {
      data.append("reason", formData.reason);
    }

    console.log("Submitting:", Object.fromEntries(data.entries()));

    try {
      await axios.post(
        "http://127.0.0.1:8000/VJISS/add_internship_offers",
        data,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      alert("Application submitted successfully ✅");

      setFormData({
        internship_offers: "",
        first_name: "",
        last_name: "",
        email: "",
        phone_number: "",
        education: "",
        resume: null,
        reason: "",
      });
    } catch (error) {
      console.error(error.response?.data || error);
      alert("Failed to submit ❌");
    }
  };

  return (
    <div className="bg-gray-50">
      {/* Hero */}
      <section className="bg-gradient-to-br from-primary to-blue-800 text-white py-20">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <h1 className="text-5xl font-bold mb-6">Internship Program</h1>
          <p className="text-xl text-blue-200">
            Launch your career with real-world internship experience
          </p>
        </div>
      </section>

      {/* Application Form */}
      <section className="py-20">
        <div className="max-w-4xl mx-auto px-4">
          <h2 className="text-4xl font-bold text-center mb-12">
            Apply for Internship
          </h2>

          <form
            className="bg-white p-8 rounded-xl shadow-lg space-y-6"
            onSubmit={handleSubmit}
          >
            {/* Internship */}
            <div>
              <label className="flex items-center mb-1 font-medium">
                Internship Role <span className="text-red-500 ml-1">*</span>
              </label>
              <select
                name="internship_offers"
                value={formData.internship_offers}
                onChange={handleChange}
                required
                className="w-full p-3 border rounded-lg"
              >
                <option value="">Select Internship</option>
                <option value="1">Web Development</option>
                <option value="2">MERN Stack</option>
                <option value="3">Python</option>
                <option value="4">Data Science</option>
              </select>
            </div>

            {/* Names */}
            <div className="grid md:grid-cols-2 gap-6">
              <input
                type="text"
                name="first_name"
                placeholder="First Name"
                value={formData.first_name}
                onChange={handleChange}
                required
                className="w-full p-3 border rounded-lg"
              />
              <input
                type="text"
                name="last_name"
                placeholder="Last Name"
                value={formData.last_name}
                onChange={handleChange}
                required
                className="w-full p-3 border rounded-lg"
              />
            </div>

            {/* Email & Phone */}
            <div className="grid md:grid-cols-2 gap-6">
              <input
                type="email"
                name="email"
                placeholder="Email"
                value={formData.email}
                onChange={handleChange}
                required
                className="w-full p-3 border rounded-lg"
              />
              <input
                type="tel"
                name="phone_number"
                placeholder="Phone Number"
                value={formData.phone_number}
                onChange={handleChange}
                pattern="[6-9][0-9]{9}"
                maxLength={10}
                required
                className="w-full p-3 border rounded-lg"
              />
            </div>

            {/* Education */}
            <select
              name="education"
              value={formData.education}
              onChange={handleChange}
              required
              className="w-full p-3 border rounded-lg"
            >
              <option value="">Select Education</option>
              <option value="Diploma">Diploma</option>
              <option value="UG">Under Graduate</option>
              <option value="PG">Post Graduate</option>
              <option value="PhD">PhD</option>
            </select>

            {/* Resume */}
            <input
              type="file"
              name="resume"
              accept=".pdf,.doc,.docx"
              required
              onChange={handleFileChange}
              className="w-full p-3 border rounded-lg"
            />

            {/* Reason (Optional) */}
            <textarea
              rows="4"
              name="reason"
              value={formData.reason}
              onChange={handleChange}
              placeholder="Why do you want to join? (Optional)"
              className="w-full p-3 border rounded-lg"
            />

            {/* Submit */}
            <button
              type="submit"
              className="w-full bg-secondary hover:bg-orange-600 text-white py-4 rounded-lg font-semibold text-lg"
            >
              Submit Application
            </button>
          </form>
        </div>
      </section>
    </div>
  );
}
